#!/bin/bash
set -e

# Split into two separate templates with PDF attached:
# - payment_receipt: Collect Payment (against invoice). Manual send
#   ONLY, via the Receipt button. Invoice No. shows joined invoice
#   numbers (a payment can span multiple invoices).
# - advance_receipt: Advance payments. Auto-sent (deferred via after()
#   for speed) AND available via the manual button. Invoice No. is
#   left blank since advances have no invoice yet.
# The Receipt button now routes to the correct template automatically
# based on the payment's type -- no change needed in receipt-tab.js.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "lib"
echo "" | base64 -d > "lib/whatsapp.js"
echo "Wrote lib/whatsapp.js"

mkdir -p "lib"
echo "" | base64 -d > "lib/pdf-generator.js"
echo "Wrote lib/pdf-generator.js"

mkdir -p "app/(main)/payments"
echo "" | base64 -d > "app/(main)/payments/actions.js"
echo "Wrote app/(main)/payments/actions.js"

git add "lib/whatsapp.js" "lib/pdf-generator.js" "app/(main)/payments/actions.js"
git commit -m "Split payment WhatsApp into payment_receipt (manual, w/ invoice) and advance_receipt (auto+manual, no invoice), both with PDF"
git push

echo "Done."
